/**
 * Body - Physics body wrapper with Three.js-like interface
 *
 * Provides `position` and `quaternion` properties that behave like
 * THREE.Vector3 and THREE.Quaternion, but read/write to SharedArrayBuffer
 * for lock-free physics synchronization. Automatically attached to API
 * objects returned by `physics.addBody()` and `physics.addBodies()`.
 *
 * **Position Methods**
 *
 * ```js
 * api.body.position.set(x, y, z)      // Set absolute position
 * api.body.position.x = 10            // Set individual component
 * api.body.position.copy(vector3)     // Copy from Vector3
 * api.body.position.add(dx, dy, dz)   // Add to current position
 * api.body.position.addVector(v)      // Add Vector3 to position
 * api.body.position.toVector3()       // Get as THREE.Vector3
 * ```
 *
 * **Quaternion Methods**
 *
 * ```js
 * api.body.quaternion.set(x, y, z, w)       // Set absolute rotation
 * api.body.quaternion.copy(quaternion)      // Copy from Quaternion
 * api.body.quaternion.identity()            // Reset to no rotation
 * api.body.quaternion.setFromEuler(euler)   // Set from Euler angles
 * api.body.quaternion.setFromAxisAngle(axis, angle)  // Set from axis-angle
 * api.body.quaternion.toQuaternion()        // Get as THREE.Quaternion
 * ```
 *
 * @example
 * ```javascript
 * // Moving a kinematic platform
 * const api = await physics.addBody(BodyType.KINEMATIC, platformMesh);
 *
 * function animate() {
 *   const time = performance.now() * 0.001;
 *   api.body.position.set(
 *     Math.sin(time) * 5,
 *     2,
 *     Math.cos(time) * 5
 *   );
 *   api.body.quaternion.setFromAxisAngle({ x: 0, y: 1, z: 0 }, time);
 * }
 * ```
 *
 * @class Body
 * @short Three.js-like interface for physics body transforms.
 * @category Core
 * @tags Physics, Body, WebGPU, WebGL
 */
export class Body {
    /**
     * Create a Body wrapper.
     *
     * @param {Object} views - Physics views object containing type-indexed body arrays.
     * @param {string} type - Body type: 'dynamic', 'kinematic', 'static', 'zone'.
     * @param {number} index - Body index in the views array.
     * @param {THREE.Object3D|null} [entity=null] - Optional entity to sync transforms to.
     * @param {Object|null} [physics=null] - Physics instance for event registration.
     */
    constructor(views: any, type: string, index: number, entity?: THREE.Object3D | null, physics?: any | null);
    _views: any;
    _type: string;
    _index: number;
    _entity: any;
    _physics: any;
    /**
     * Scale for sync(). Extracted from mesh matrixWorld or instance matrix at body creation.
     * @type {THREE.Vector3}
     * @private
     */
    private _scale;
    /**
     * Instance index for BatchedMesh/InstancedMesh. Set by addBody.
     * @type {number|undefined}
     * @private
     */
    private _instanceIndex;
    /**
     * Three.js-style type flag. Always true for Body instances.
     * @type {boolean}
     * @readonly
     */
    readonly isBody: boolean;
    /**
     * EventDispatcher listener storage.
     * @private
     */
    private _listeners;
    /**
     * Tracks which event types have been registered with the worker.
     * @private
     */
    private _registeredEvents;
    /**
     * Position interface with THREE.Vector3-like methods.
     * Changes are written to SharedArrayBuffer and optionally synced to entity mesh.
     * @type {Object}
     */
    position: any;
    /**
     * Quaternion interface with THREE.Quaternion-like methods.
     * Changes are written to SharedArrayBuffer and optionally synced to entity mesh.
     * @type {Object}
     */
    quaternion: any;
    /**
     * Add an event listener for a body event.
     * Automatically registers the event with the physics worker on first listener.
     *
     * @param {string} type - Event type (use BodyEvent constants)
     * @param {Function} listener - Callback function
     * @example
     * ```js
     * import { BodyEvent } from '@three-blocks/pro';
     * body.addEventListener(BodyEvent.HIT, (event) => {
     *   console.log('Hit at:', event.hitPoint);
     * });
     * ```
     */
    addEventListener(type: string, listener: Function): void;
    /**
     * Check if an event listener exists for a body event.
     *
     * @param {string} type - Event type
     * @param {Function} listener - Callback function
     * @returns {boolean} True if listener exists
     */
    hasEventListener(type: string, listener: Function): boolean;
    /**
     * Remove an event listener for a body event.
     * Automatically unregisters from the physics worker when no listeners remain.
     *
     * @param {string} type - Event type
     * @param {Function} listener - Callback function to remove
     */
    removeEventListener(type: string, listener: Function): void;
    /**
     * Dispatch an event to all registered listeners.
     *
     * @param {Object} event - Event object with `type` property
     */
    dispatchEvent(event: any): void;
    /**
     * Register event type with physics worker.
     * Called automatically when first listener is added for an event type.
     * @private
     */
    private _registerEventWithWorker;
    /**
     * Unregister event type from physics worker.
     * Called automatically when last listener is removed for an event type.
     * @private
     */
    private _unregisterEventFromWorker;
    /**
     * The body index in the physics system.
     * @type {number}
     * @readonly
     */
    readonly get index(): number;
    /**
     * The body type ('dynamic', 'kinematic', 'static', 'zone').
     * @type {string}
     * @readonly
     */
    readonly get type(): string;
    /**
     * The associated Three.js entity (mesh/group).
     * @type {THREE.Object3D|null}
     * @readonly
     */
    readonly get entity(): THREE.Object3D | null;
    /**
     * Direct access to the raw BBO view for advanced usage.
     * @type {Object|null}
     * @readonly
     */
    readonly get view(): any | null;
    set scale(v: THREE.Vector3);
    /**
     * Scale used by sync() for mesh transforms.
     * Set automatically from mesh matrixWorld or instance matrix during body creation.
     * @type {THREE.Vector3}
     */
    get scale(): THREE.Vector3;
    /**
     * Angular velocity in radians per second (local space).
     * Only used when `enableRotationResponse` is true.
     *
     * @type {{ x: number, y: number, z: number, set: Function, copy: Function, toVector3: Function }}
     * @example
     * ```js
     * // Set angular velocity directly
     * api.body.angularVelocity.set(0, 1, 0); // Spin around Y axis
     *
     * // Copy from Vector3
     * api.body.angularVelocity.copy(torqueVector);
     *
     * // Read current values
     * console.log(api.body.angularVelocity.x, api.body.angularVelocity.y, api.body.angularVelocity.z);
     * ```
     */
    get angularVelocity(): {
        x: number;
        y: number;
        z: number;
        set: Function;
        copy: Function;
        toVector3: Function;
    };
    /**
     * Linear velocity in units per second (world space).
     * Use this to give bodies an initial velocity or modify velocity during gameplay.
     *
     * @type {{ x: number, y: number, z: number, set: Function, copy: Function, toVector3: Function }}
     * @example
     * ```js
     * // Set linear velocity directly
     * api.body.velocity.set(10, 5, 0); // Move right and up
     *
     * // Copy from Vector3
     * api.body.velocity.copy(directionVector.multiplyScalar(speed));
     *
     * // Read current values
     * console.log(api.body.velocity.x, api.body.velocity.y, api.body.velocity.z);
     * ```
     */
    get velocity(): {
        x: number;
        y: number;
        z: number;
        set: Function;
        copy: Function;
        toVector3: Function;
    };
    set angularDamping(value: number);
    /**
     * Angular damping factor (0 = no damping, 1 = instant stop).
     * Applied each physics step when `enableRotationResponse` is true.
     * Default: 0.1
     *
     * @type {number}
     * @example
     * ```js
     * api.body.angularDamping = 0.05; // Low damping - spins longer
     * api.body.angularDamping = 0.3;  // High damping - stops quickly
     * ```
     */
    get angularDamping(): number;
    set enableRotationResponse(value: boolean);
    /**
     * Enable rotation response during collisions.
     * When disabled (default), only position is affected by collisions.
     * When enabled, collisions apply angular impulses causing objects to spin and roll.
     *
     * @type {boolean}
     * @example
     * ```js
     * // Enable rotation physics for realistic rolling spheres
     * api.body.enableRotationResponse = true;
     *
     * // Disable for position-only physics (better performance)
     * api.body.enableRotationResponse = false;
     * ```
     */
    get enableRotationResponse(): boolean;
    set enableCCD(value: boolean);
    /**
     * Continuous Collision Detection (CCD) enabled.
     * When enabled, uses speculative contacts to prevent fast-moving bodies from
     * tunneling through geometry. Useful for character controllers at high speeds.
     *
     * @type {boolean}
     * @default false
     * @example
     * ```js
     * // Enable CCD for fast-moving player
     * api.body.enableCCD = true;
     *
     * // Disable for better performance when not needed
     * api.body.enableCCD = false;
     * ```
     */
    get enableCCD(): boolean;
    set momentOfInertia(value: number);
    /**
     * Moment of inertia (scalar approximation).
     * Auto-calculated from mass and collision shape during body creation.
     * Can be overridden for custom physics behavior.
     *
     * @type {number}
     * @example
     * ```js
     * // Read auto-calculated inertia
     * console.log(api.body.momentOfInertia);
     *
     * // Override for heavier feel
     * api.body.momentOfInertia = 10;
     * ```
     */
    get momentOfInertia(): number;
    /**
     * Synchronize physics state to the entity mesh with interpolation.
     *
     * Applies position, quaternion, and scale to the mesh.
     * For BatchedMesh/InstancedMesh, updates the instance matrix.
     * For regular meshes, sets position/quaternion/scale properties directly.
     *
     * Scale is stored on body creation (from instance matrix for BatchedMesh)
     * and can be changed via `body.scale.set(x, y, z)`.
     *
     * @param {number} [alpha=1] - Interpolation factor (0-1). Use `controller.getInterpolationAlpha()`.
     * @returns {Body} Returns `this` for chaining.
     * @example
     * ```javascript
     * // In animation loop
     * const alpha = controller.getInterpolationAlpha();
     * playerBody.sync(alpha);
     *
     * // Change scale (applies on next sync)
     * playerBody.scale.set(1.5, 1.5, 1.5);
     *
     * // For BatchedMesh instances
     * for (const bodyApi of dynamicBodyApis) {
     *   bodyApi.body.sync(alpha);
     * }
     * ```
     */
    sync(alpha?: number): Body;
    /**
     * Dispose of the body, cleaning up all event listeners.
     * Called automatically by Physics.removeBody().
     *
     * @example
     * ```javascript
     * // Usually called via physics.removeBody()
     * await physics.removeBody(api);
     *
     * // Can also be called directly if needed
     * api.body.dispose();
     * ```
     */
    dispose(): void;
}
export default Body;
